-- RN1 independent chronological ledger: strictly disjoint from 3 original pilot markets.
-- Fixed deterministic stratification: 4 SHA-ordered markets from each of
-- MERGE only, MERGE + REDEEM, REDEEM only, and trades only.
-- September 15-28, 2026, between 2 and 30 BUY fills, duration under 20h.
-- Sources: privately stored trades_all/activity_all gzip pages, SHA-256 validated.
-- Input events are not a complete on-chain wallet transfer ledger.
create table if not exists pi.rn1_ledger_holdout_selection(
 market_key text primary key,
 cohort text not null check(cohort in('merge_only','merge_redeem','redeem_only','trade_only')),
 cohort_rank integer not null check(cohort_rank between 1 and 4),
 title text, expected_fills integer not null,
 trade_start timestamptz,trade_end timestamptz,
 expected_merges integer not null,expected_redeems integer not null,
 sample_version text not null default 'rn1-independent-ledger-20261118-v1',
 selected_at timestamptz not null default now(),
 unique(sample_version,cohort,cohort_rank)
);
create table if not exists pi.rn1_ledger_holdout_audit(
 market_key text primary key references pi.rn1_ledger_holdout_selection(market_key),
 cohort text not null,cohort_rank int not null,title text,
 verified_pages int not null,source_trade_fills int not null,
 source_merge_events int not null,source_redeem_events int not null,
 buy_spend numeric not null,sell_proceeds numeric not null,
 merge_in numeric not null,redeem_in numeric not null,
 gross_cash_net numeric not null,terminal0 numeric not null,terminal1 numeric not null,
 minimum_running0 numeric not null,minimum_running1 numeric not null,
 source_fills_match boolean not null,source_activity_match boolean not null,
 inventory_nonnegative boolean not null,evidence_status text not null,
 timeline jsonb not null,source_response_id bigint not null,
 observed_first_at timestamptz,observed_last_at timestamptz,
 audited_at timestamptz not null default now()
);
alter table pi.rn1_ledger_holdout_selection enable row level security;
alter table pi.rn1_ledger_holdout_audit enable row level security;
revoke all on pi.rn1_ledger_holdout_selection,pi.rn1_ledger_holdout_audit from anon,authenticated;
-- Frozen selection snapshot: research protocol was defined BEFORE inspecting outcomes.
